// buildUsersWhere 构建过滤 WHERE 条件,List 与 Count 共用,过滤结果一致。
// 所有值均经占位符参数化,列名与操作符为白名单字面量。
//
// 参数:
//   - params: 已通过 validate 形态复核的查询参数。
//
// 返回值:
//   - []sq.Sqlizer: 按 AND 语义组合的过滤条件列表。
func buildUsersWhere(params ListUsersParams) []sq.Sqlizer {
	var conds []sq.Sqlizer
	if params.ID != nil {
		conds = append(conds, sq.Eq{"id": *params.ID})
	}
	if params.IDNeq != nil {
		conds = append(conds, sq.NotEq{"id": *params.IDNeq})
	}
	if params.IDIn != nil {
		conds = append(conds, sq.Eq{"id": params.IDIn})
	}
	if params.IDNotIn != nil {
		conds = append(conds, sq.NotEq{"id": params.IDNotIn})
	}
	if params.Name != nil {
		conds = append(conds, sq.Eq{"name": *params.Name})
	}
	if params.NameNeq != nil {
		conds = append(conds, sq.NotEq{"name": *params.NameNeq})
	}
	if params.NameContains != "" {
		conds = append(conds, sq.Expr("name ILIKE ? ESCAPE '\\'", dynq.ContainsPattern(params.NameContains)))
	}
	if params.NamePrefix != "" {
		conds = append(conds, sq.Expr("name ILIKE ? ESCAPE '\\'", dynq.PrefixPattern(params.NamePrefix)))
	}
	if params.NameSuffix != "" {
		conds = append(conds, sq.Expr("name ILIKE ? ESCAPE '\\'", dynq.SuffixPattern(params.NameSuffix)))
	}
	if params.Email != nil {
		conds = append(conds, sq.Eq{"email": *params.Email})
	}
	if params.EmailNeq != nil {
		conds = append(conds, sq.NotEq{"email": *params.EmailNeq})
	}
	if params.EmailIn != nil {
		conds = append(conds, sq.Eq{"email": params.EmailIn})
	}
	if params.EmailNotIn != nil {
		conds = append(conds, sq.NotEq{"email": params.EmailNotIn})
	}
	if params.EmailPrefix != "" {
		conds = append(conds, sq.Expr("email ILIKE ? ESCAPE '\\'", dynq.PrefixPattern(params.EmailPrefix)))
	}
	if params.Status != nil {
		conds = append(conds, sq.Expr("status = ?::user_status", *params.Status))
	}
	if params.StatusNeq != nil {
		conds = append(conds, sq.Expr("status <> ?::user_status", *params.StatusNeq))
	}
	if params.StatusIn != nil {
		conds = append(conds, sq.Expr("status IN ("+dynq.PlaceholdersCast(len(params.StatusIn), "::user_status")+")", dynq.Anys(params.StatusIn)...))
	}
	if params.StatusNotIn != nil {
		conds = append(conds, sq.Expr("status NOT IN ("+dynq.PlaceholdersCast(len(params.StatusNotIn), "::user_status")+")", dynq.Anys(params.StatusNotIn)...))
	}
	if params.RoleContains != "" {
		conds = append(conds, sq.Expr("role ILIKE ? ESCAPE '\\'", dynq.ContainsPattern(params.RoleContains)))
	}
	if params.RolePrefix != "" {
		conds = append(conds, sq.Expr("role ILIKE ? ESCAPE '\\'", dynq.PrefixPattern(params.RolePrefix)))
	}
	if params.RoleSuffix != "" {
		conds = append(conds, sq.Expr("role ILIKE ? ESCAPE '\\'", dynq.SuffixPattern(params.RoleSuffix)))
	}
	if params.Age != nil {
		conds = append(conds, sq.Eq{"age": *params.Age})
	}
	if params.AgeNeq != nil {
		conds = append(conds, sq.NotEq{"age": *params.AgeNeq})
	}
	if params.AgeIn != nil {
		conds = append(conds, sq.Eq{"age": params.AgeIn})
	}
	if params.AgeNotIn != nil {
		conds = append(conds, sq.NotEq{"age": params.AgeNotIn})
	}
	if params.AgeGt != nil {
		conds = append(conds, sq.Gt{"age": *params.AgeGt})
	}
	if params.AgeGte != nil {
		conds = append(conds, sq.GtOrEq{"age": *params.AgeGte})
	}
	if params.AgeLt != nil {
		conds = append(conds, sq.Lt{"age": *params.AgeLt})
	}
	if params.AgeLte != nil {
		conds = append(conds, sq.LtOrEq{"age": *params.AgeLte})
	}
	if params.ScoreGt != nil {
		conds = append(conds, sq.Gt{"score": *params.ScoreGt})
	}
	if params.ScoreGte != nil {
		conds = append(conds, sq.GtOrEq{"score": *params.ScoreGte})
	}
	if params.ScoreLt != nil {
		conds = append(conds, sq.Lt{"score": *params.ScoreLt})
	}
	if params.ScoreLte != nil {
		conds = append(conds, sq.LtOrEq{"score": *params.ScoreLte})
	}
	if params.BalanceGt != nil {
		conds = append(conds, sq.Gt{"balance": *params.BalanceGt})
	}
	if params.BalanceGte != nil {
		conds = append(conds, sq.GtOrEq{"balance": *params.BalanceGte})
	}
	if params.BalanceLt != nil {
		conds = append(conds, sq.Lt{"balance": *params.BalanceLt})
	}
	if params.BalanceLte != nil {
		conds = append(conds, sq.LtOrEq{"balance": *params.BalanceLte})
	}
	if params.BirthDate != nil {
		conds = append(conds, sq.Eq{"birth_date": *params.BirthDate})
	}
	if params.BirthDateGt != nil {
		conds = append(conds, sq.Gt{"birth_date": *params.BirthDateGt})
	}
	if params.BirthDateGte != nil {
		conds = append(conds, sq.GtOrEq{"birth_date": *params.BirthDateGte})
	}
	if params.BirthDateLt != nil {
		conds = append(conds, sq.Lt{"birth_date": *params.BirthDateLt})
	}
	if params.BirthDateLte != nil {
		conds = append(conds, sq.LtOrEq{"birth_date": *params.BirthDateLte})
	}
	if params.OrgID != nil {
		conds = append(conds, sq.Expr("org_id = ?::uuid", *params.OrgID))
	}
	if params.OrgIDNeq != nil {
		conds = append(conds, sq.Expr("org_id <> ?::uuid", *params.OrgIDNeq))
	}
	if params.OrgIDIn != nil {
		conds = append(conds, sq.Expr("org_id IN ("+dynq.PlaceholdersCast(len(params.OrgIDIn), "::uuid")+")", dynq.Anys(params.OrgIDIn)...))
	}
	if params.OrgIDNotIn != nil {
		conds = append(conds, sq.Expr("org_id NOT IN ("+dynq.PlaceholdersCast(len(params.OrgIDNotIn), "::uuid")+")", dynq.Anys(params.OrgIDNotIn)...))
	}
	if params.TagsIn != nil {
		conds = append(conds, sq.Expr("tags && ?::int4[]", params.TagsIn))
	}
	if params.MetaHas != nil {
		conds = append(conds, sq.Expr("meta @> ?::jsonb", string(params.MetaHas)))
	}
	if params.CreatedAt != nil {
		conds = append(conds, sq.Eq{"created_at": *params.CreatedAt})
	}
	if params.CreatedAtNeq != nil {
		conds = append(conds, sq.NotEq{"created_at": *params.CreatedAtNeq})
	}
	if params.CreatedAtIn != nil {
		conds = append(conds, sq.Eq{"created_at": params.CreatedAtIn})
	}
	if params.CreatedAtNotIn != nil {
		conds = append(conds, sq.NotEq{"created_at": params.CreatedAtNotIn})
	}
	if params.CreatedAtGt != nil {
		conds = append(conds, sq.Gt{"created_at": *params.CreatedAtGt})
	}
	if params.CreatedAtGte != nil {
		conds = append(conds, sq.GtOrEq{"created_at": *params.CreatedAtGte})
	}
	if params.CreatedAtLt != nil {
		conds = append(conds, sq.Lt{"created_at": *params.CreatedAtLt})
	}
	if params.CreatedAtLte != nil {
		conds = append(conds, sq.LtOrEq{"created_at": *params.CreatedAtLte})
	}
	if params.UpdatedAtGt != nil {
		conds = append(conds, sq.Gt{"updated_at": *params.UpdatedAtGt})
	}
	if params.UpdatedAtGte != nil {
		conds = append(conds, sq.GtOrEq{"updated_at": *params.UpdatedAtGte})
	}
	if params.UpdatedAtLt != nil {
		conds = append(conds, sq.Lt{"updated_at": *params.UpdatedAtLt})
	}
	if params.UpdatedAtLte != nil {
		conds = append(conds, sq.LtOrEq{"updated_at": *params.UpdatedAtLte})
	}
	if params.UpdatedAtIsNull {
		conds = append(conds, sq.Expr("updated_at IS NULL"))
	}
	if params.UpdatedAtNotNull {
		conds = append(conds, sq.Expr("updated_at IS NOT NULL"))
	}
	if params.DeletedAtIsNull {
		conds = append(conds, sq.Expr("deleted_at IS NULL"))
	}
	if params.DeletedAtNotNull {
		conds = append(conds, sq.Expr("deleted_at IS NOT NULL"))
	}
	return conds
}

// usersCursorValues 提取用于构造 nextCursor 的排序列值,顺序与有效排序一致。
//
// 参数:
//   - row: 查询结果中的一行模型。
//   - seq: 排序列及方向,顺序与游标值顺序一致。
//
// 返回值:
//   - []any: 与 seq 一一对应的列值切片。
func usersCursorValues(row User, seq []dynq.SortField) []any {
	vals := make([]any, len(seq))
	for i, sf := range seq {
		switch sf.Key {
		case "id":
			vals[i] = row.ID
		case "name":
			vals[i] = row.Name
		case "status":
			vals[i] = string(row.Status)
		case "role":
			vals[i] = row.Role
		case "age":
			vals[i] = row.Age
		case "score":
			vals[i] = row.Score
		case "createdAt":
			vals[i] = row.CreatedAt
		case "updatedAt":
			vals[i] = row.UpdatedAt
		default:
			vals[i] = nil
		}
	}
	return vals
}

// ListUsers 按 params 的过滤、排序、投影与分页条件查询列表页。
// 返回本页行、是否还有下一页与续翻游标;total 由 CountUsers 单独计算
// (非强一致快照)。生成代码为纯函数,不持有连接状态。
// 未查询列在结果中留零值(动态投影固有语义),需区分时按请求 fields 做 DTO 化。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,可由 ParseUsersQuery 产出或直接构造。
//   - opts:   运行期能力收窄选项;禁用目标不在 registry 时返回错误。
//
// 返回值:
//   - dynq.Result[User]: 本页行、是否还有下一页与续翻游标。
//   - error:              查询或校验失败时的错误。
func ListUsers(ctx context.Context, db DBTX, params ListUsersParams, opts ...dynq.QueryOption) (dynq.Result[User], error) {
	cfg, err := dynq.NewQueryConfig(usersRegistry, opts...)
	if err != nil {
		return dynq.Result[User]{}, err
	}
	if err := validateUsersParams(params, cfg); err != nil {
		return dynq.Result[User]{}, err
	}
	limit, err := dynq.CheckPagination(usersRegistry, params.Limit, params.Offset, params.After)
	if err != nil {
		return dynq.Result[User]{}, err
	}
	// 解析有效排序:未指定排序时回落表级 @default_sort。
	seq, err := dynq.ResolveSort(usersRegistry, cfg, params.OrderBy)
	if err != nil {
		return dynq.Result[User]{}, err
	}
	fp := dynq.CursorFingerprint(usersRegistry.Resource, seq)
	// 计算 SELECT 列:投影列并集排序列(排序所需列始终参与查询)。
	cols := dynq.SelectColumns(usersRegistry, params.SelectFields, seq)
	b := sq.Select(cols...).From("users").PlaceholderFormat(sq.Dollar).Where(sq.And(buildUsersWhere(params))).
		OrderBy(dynq.OrderBySQL(seq)).Limit(uint64(limit) + 1)
	// After 非 nil 时为游标模式:解码并校验游标,从该位置继续读取。
	if params.After != nil {
		vals, err := dynq.DecodeCursor(*params.After, fp, seq)
		if err != nil {
			return dynq.Result[User]{}, err
		}
		seek, err := dynq.SeekPredicate(seq, vals)
		if err != nil {
			return dynq.Result[User]{}, err
		}
		b = b.Where(seek)
	}
	if params.Offset > 0 {
		b = b.Offset(uint64(params.Offset))
	}
	query, args, err := b.ToSql()
	if err != nil {
		return dynq.Result[User]{}, err
	}
	rows, err := db.Query(ctx, query, args...)
	if err != nil {
		return dynq.Result[User]{}, err
	}
	items, err := pgx.CollectRows(rows, pgx.RowToStructByNameLax[User])
	if err != nil {
		return dynq.Result[User]{}, err
	}
	// 以 LIMIT n+1 探测是否还有下一页,并构造 nextCursor。
	hasMore := len(items) > int(limit)
	if hasMore {
		items = items[:limit]
	}
	var next string
	if hasMore {
		next, err = dynq.EncodeCursor(fp, seq, usersCursorValues(items[len(items)-1], seq))
		if err != nil {
			return dynq.Result[User]{}, err
		}
	}
	return dynq.Result[User]{Items: items, HasMore: hasMore, NextCursor: next}, nil
}

// CountUsers 统计满足过滤条件的行数,与分页模式和游标位置无关;
// 忽略投影、排序与游标。
//
// 参数:
//   - ctx:    查询上下文。
//   - db:     数据库连接,满足 DBTX 接口即可。
//   - params: typed 查询参数,与 ListUsers 使用同一份形态复核。
//   - opts:   运行期能力收窄选项。
//
// 返回值:
//   - int64: 满足过滤条件的行数。
//   - error: 查询或校验失败时返回错误。
func CountUsers(ctx context.Context, db DBTX, params ListUsersParams, opts ...dynq.QueryOption) (int64, error) {
	cfg, err := dynq.NewQueryConfig(usersRegistry, opts...)
	if err != nil {
		return 0, err
	}
	if err := validateUsersParams(params, cfg); err != nil {
		return 0, err
	}
	if _, err := dynq.CheckPagination(usersRegistry, params.Limit, params.Offset, params.After); err != nil {
		return 0, err
	}
	query, args, err := sq.Select("COUNT(*)").From("users").PlaceholderFormat(sq.Dollar).Where(sq.And(buildUsersWhere(params))).ToSql()
	if err != nil {
		return 0, err
	}
	var total int64
	if err := db.QueryRow(ctx, query, args...).Scan(&total); err != nil {
		return 0, err
	}
	return total, nil
}

// UsersQuerySchema 是前端契约出口:返回经 opts 减法投影后的有效能力全集,
// 前端据此渲染查询组件。Schema 是(生成期元数据, opts)的确定性纯函数,
// 同一 opts 产出字节级相同结果,内容 hash 可作 ETag;被禁用字段不出现于 schema。
//
// 参数:
//   - opts: 运行期能力收窄选项,须与 Parse/List/Count 使用同一份 opts。
//
// 返回值:
//   - dynq.ResourceSchema: 前端渲染所需的能力描述(字段、操作符、排序、分页配置)。
func UsersQuerySchema(opts ...dynq.QueryOption) dynq.ResourceSchema {
	cfg, err := dynq.NewQueryConfig(usersRegistry, opts...)
	if err != nil {
		// 禁用目标不在 registry 属于编程错误。Parse/List/Count/Schema 四点同参纪律
		// 下,此处 panic 显式暴露;静默吞错会掩盖权限收窄失效。
		panic(err)
	}
	return dynq.BuildSchema(usersRegistry, cfg)
}
